sp_widget.client_script:
api.controller = function($scope, spUtil, $element) {

    /* widget controller */
    var c = this;
    var g_form = $scope.page.g_form;

    $scope.$watch(function() {
        return g_form.getValue('short_description'); // Replace 'your_field_name' with the actual field name
    }, function(newValue, oldValue) {
        var newCharactersLength = newValue.length;

        if (newCharactersLength != 0) {

            var charactersLeft = 160 - parseInt(newCharactersLength);
            c.data.isVisible = true;

            if (newCharactersLength < 160) {
                c.data.counterMessage = '';
                c.data.textColor = "#806d6c";
                c.data.counterMessage = charactersLeft + " characters remaining of 160 characters";
            } else if (newCharactersLength == 160) {
                c.data.counterMessage = '';
                c.data.textColor = "#e0170e";
                c.data.counterMessage = "The characters' length has reached its maximum length.";
            } else {
                c.data.counterMessage = '';
                c.data.textColor = "#e0170e";
                c.data.counterMessage = "The length of the characters entered exceeds 160.";
            }
        } else {
            c.data.isVisible = false;
        }
    });







    /*c.getFocusedElementAttributes = function() {
